#include <bits/stdc++.h>
using namespace std;

struct UnionFindSet {
    vector<int> parent, rank;
    void init(int n) {
        parent.resize(n);
        rank.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            rank[i] = 0;
        }
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void merge(int a, int b) {
        a = find(a);
        b = find(b);
        if (a != b) {
            if (rank[a] < rank[b]) swap(a, b);
            parent[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }
    }
};

long long bin_pow(long long base, int exp, int mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    const int MOD = 1e9 + 7;
    if (k == 0) {
        cout << bin_pow(n, n - 1, MOD) << "\n";
        return 0;
    }
    UnionFindSet ufs;
    ufs.init(n);
    for (int i = 0; i < n; ++i) {
        ufs.merge(i, (long long)i * k % n);
    }
    long long result = 1;
    for (int i = 0; i < n; ++i) {
        if (ufs.find(i) != i) continue;
        long long t = bin_pow(k, ufs.rank[ufs.find(i)], n);
        if (t == 1) {
            result = (result * n) % MOD;
        }
    }
    cout << result << "\n";
}
